#!/usr/bin/env node
/**
 * Render the command docs from the checked-in contract, so nobody hand-writes them.
 *
 *   node scripts/render-docs.mjs           rewrite docs/commands.md and the README overview
 *   node scripts/render-docs.mjs --check   exit 1 if either is stale (what the test runs)
 *
 * The source is docs/cli-contract.json (itself generated by `capcutctl contract`, and held
 * fresh by test/cli-contract.test.mjs). docs/commands.md is the full reference, rendered by
 * the same function as `capcutctl contract --markdown`. The README gets a compact overview,
 * one row per workflow group, between the two COMMANDS markers.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { GROUPS, renderReference } from '../src/command-docs.mjs';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONTRACT = 'docs/cli-contract.json';
const REFERENCE = 'docs/commands.md';
const README = 'README.md';
const BEGIN = '<!-- COMMANDS:BEGIN generated by scripts/render-docs.mjs from docs/cli-contract.json; do not edit by hand -->';
const END = '<!-- COMMANDS:END -->';

const read = file => fs.readFileSync(path.join(ROOT, file), 'utf8');

// GitHub's heading anchors: lower-case, punctuation dropped, spaces to hyphens.
const anchor = title => title.toLowerCase().replace(/[^a-z0-9 -]/g, '').trim().replace(/ /g, '-');

export function renderOverview(contract) {
  const lines = [
    BEGIN,
    '',
    `${Object.keys(contract.commands).length} commands (CLI ${contract.cliVersion}, contract v${contract.contractVersion}). `
      + '**T** marks a transactional edit: snapshot, validate, roll back on failure, and `--dry-run`.',
    '',
    '| Stage | Commands |',
    '|---|---|',
  ];
  for (const [group, title] of GROUPS) {
    const names = Object.entries(contract.commands)
      .filter(([, c]) => c.group === group)
      .map(([name, c]) => `\`${name}\`${c.transactional ? ' **T**' : ''}`);
    if (names.length) lines.push(`| [${title}](${REFERENCE}#${anchor(title)}) | ${names.join(', ')} |`);
  }
  lines.push('', `Every command with its purpose, an example and every option: [${REFERENCE}](${REFERENCE}).`, '', END);
  return lines.join('\n');
}

export function render() {
  const contract = JSON.parse(read(CONTRACT));
  const readme = read(README);
  const start = readme.indexOf(BEGIN);
  const stop = readme.indexOf(END);
  if (start < 0 || stop < start) throw new Error(`${README} has no COMMANDS:BEGIN/END block`);
  return {
    [REFERENCE]: renderReference(contract),
    [README]: readme.slice(0, start) + renderOverview(contract) + readme.slice(stop + END.length),
  };
}

// Compare real paths: argv[1] is the path as typed, import.meta.url is already resolved, so
// a symlinked clone (or /tmp against /private/tmp on macOS) would otherwise skip the CLI
// silently, and --check would pass on stale docs.
const realpath = file => { try { return fs.realpathSync(file); } catch { return file; } };
if (process.argv[1] && realpath(process.argv[1]) === realpath(fileURLToPath(import.meta.url))) {
  const check = process.argv.includes('--check');
  const stale = [];
  for (const [file, text] of Object.entries(render())) {
    const target = path.join(ROOT, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
    if (current === text) continue;
    if (check) stale.push(file);
    else fs.writeFileSync(target, text);
  }
  if (stale.length) {
    console.error(`stale: ${stale.join(', ')} (run node scripts/render-docs.mjs)`);
    process.exitCode = 1;
  }
}
